/* ------------------------------------------------------------------ */
/* 3. As linhas que não dizem de quem são                              */
/* ------------------------------------------------------------------ */

-- 91 linhas de 2024 trazem o TIME no lugar do nome: "rem comercial",
-- "escala suporte", "comissao sucesso". São R$ 81.420,00 de remuneração de
-- verdade, que tem de entrar na soma da área e do mês — mas pendurar em alguém
-- seria inventar. Entram como balde, com `eh_pessoa = false`, que é o mesmo
-- interruptor que já mantém empresa fora de mediana, percentil e comparação com
-- pares (`filtrarPessoas`, `compararComPares`, `custoPorArea`).
select v.nome, public.contraparte_chave(v.nome), false, v.obs
  from (values
    ('Sem nome no extrato (Suporte)', 'Linhas de 2024 em que o extrato escreveu o time no lugar do nome. Não é pessoa: é balde de área.'),
    ('Sem nome no extrato (Onboarding)', 'Linhas de 2024 em que o extrato escreveu o time no lugar do nome. Não é pessoa: é balde de área.'),
    ('Sem nome no extrato (Sucesso)', 'Linhas de 2024 em que o extrato escreveu o time no lugar do nome. Não é pessoa: é balde de área.'),
    ('Sem nome no extrato (Comercial)', 'Linhas de 2024 em que o extrato escreveu o time no lugar do nome. Não é pessoa: é balde de área.'),
    ('Sem nome no extrato (Tecnologia)', 'Linhas de 2024 em que o extrato escreveu o time no lugar do nome. Não é pessoa: é balde de área.'),
    ('Sem nome no extrato (Marketing)', 'Linhas de 2024 em que o extrato escreveu o time no lugar do nome. Não é pessoa: é balde de área.')
  ) as v(nome, obs)
 where public.remuneracao_pessoa_por_chave(public.contraparte_chave(v.nome)) is null
on conflict (chave) do nothing;

/* ------------------------------------------------------------------ */
/* 4. Os 806 pagamentos de dez/2023 a nov/2024                        */
/* ------------------------------------------------------------------ */

create temporary table _remuneracao_ca24 (
  pessoa      text not null,
  competencia date not null,
  bloco       text not null,
  valor       numeric(14,2) not null,
  origem_ref  text not null,
  categoria   text not null,
  vencimento  date not null,
  pagamento   date
) on commit drop;


do $$
declare v_orfaos text;
begin
  select string_agg(distinct t.pessoa, ', ') into v_orfaos
    from _remuneracao_ca24 t
   where public.remuneracao_pessoa_por_chave(public.contraparte_chave(t.pessoa)) is null;
  if v_orfaos is not null then
    raise exception 'Remuneração/Conta Azul 2024: sem pessoa no cadastro para %', v_orfaos;
  end if;
end $$;

select public.remuneracao_pessoa_por_chave(public.contraparte_chave(t.pessoa)),
       t.competencia, t.bloco, t.valor, 'conta_azul', t.origem_ref,
       t.categoria, t.vencimento, t.pagamento
  from _remuneracao_ca24 t
on conflict (fonte, origem_ref) do update
  set valor         = excluded.valor,
      competencia   = excluded.competencia,
      bloco         = excluded.bloco,
      categoria     = excluded.categoria,
      vencimento    = excluded.vencimento,
      pagamento     = excluded.pagamento,
      pessoa_id     = excluded.pessoa_id,
      atualizado_em = now();

/* ------------------------------------------------------------------ */
/* 5. Conferência contra a DRE de 2024                                 */
/* ------------------------------------------------------------------ */

-- Deslocada em um mês, porque a DRE de 2024 é caixa. Fora jan/24 e fev/24, que
-- são os dois lados do R$ 191,25 que o contador moveu de mês; e fora dez/2023,
-- que é a ponta parcial da série.
do $$
declare
  r      record;
  v_prem numeric;
  v_dre  numeric;
begin
  for r in
    select * from (values
      ('2024-03-01'::date, 'Apr-24'), ('2024-04-01'::date, 'May-24'),
      ('2024-05-01'::date, 'Jun-24'), ('2024-06-01'::date, 'Jul-24'),
      ('2024-07-01'::date, 'Aug-24'), ('2024-08-01'::date, 'Sep-24'),
      ('2024-09-01'::date, 'Oct-24'), ('2024-10-01'::date, 'Nov-24'),
      ('2024-11-01'::date, 'Dec-24')
    ) as c(competencia, chave_dre)
  loop
    select coalesce(sum(l.valor), 0) into v_prem
      from public.remuneracao_lancamento l
     where l.competencia = r.competencia and l.bloco = 'premiacao';

    select coalesce(sum(abs(nullif(linha.value ->> r.chave_dre, '')::numeric)), 0) into v_dre
      from public.demonstracoes_contabeis d,
           lateral jsonb_array_elements(d.dados -> 'rows') linha
     where d.tipo = 'dre' and d.periodo = 'completo'
       and linha.value ->> 'Conta' in ('Premiações', 'Premiações Operacionais');

    if v_dre > 0 and abs(v_dre - v_prem) > 1 then
      raise exception 'Remuneração/% : premiação R$ % não bate com a DRE (R$ %)',
        r.chave_dre, v_prem, v_dre;
    end if;
  end loop;
end $$;
